from langchain.agents import create_agent
from langchain.tools import tool
from langgraph.checkpoint.postgres import PostgresSaver
from langgraph.types import Command, interrupt

@tool
def get_transaction(utr: str) -> dict:
    """Look up a UPI transaction by its 12-digit UTR."""
    return bank.transactions.get(utr)

@tool
def raise_dispute(utr: str, reason: str) -> str:
    """Raise a dispute for a failed UPI debit. Needs human approval."""
    decision = interrupt({"utr": utr, "reason": reason})    # run pauses here
    if decision != "approve":
        return "Rejected by reviewer."
    return bank.disputes.create(utr, reason)

with PostgresSaver.from_conn_string(DB_URL) as saver:
    saver.setup()                                            # first run only
    agent = create_agent("anthropic:claude-sonnet-4-5",
                         tools=[get_transaction, raise_dispute],
                         system_prompt=SYSTEM, checkpointer=saver)
    case = {"configurable": {"thread_id": "case-8812"}}
    agent.invoke({"messages": [{"role": "user", "content": QUESTION}]}, case)

    # Hours later, in another process, after the reviewer approves:
    agent.invoke(Command(resume="approve"), case)
